	/**
	 * Pattern {@code ?s
	 *
	<p>
	 *  ?o} with the object bound: on {@code spoc,posc} the posc prefix covers p and o.
	 */
	@Test
	void coveredPrefixIsPricedAsSeekPlusMatchingRows() throws IOException {
		try (Fixture fixture = Fixture.open(directory.resolve("covered"), "spoc,posc", false)) {
			LmdbNativeAccessFacts.Quote quote = fixture.quote(LmdbNativeAccessFacts.PREDICATE
					| LmdbNativeAccessFacts.OBJECT);
			assertThat(quote.lmdb().known()).as("covered prefix has a finite ceiling: %s", quote).isTrue();
			assertThat(quote.adjacency()).as("no adjacency index configured").isNull();
			double rowsPerObject = (double) SUBJECTS / OBJECTS;
			assertThat(quote.lmdb().high())
					.as("ceiling is one seek plus the matching rows, not a sweep: %s", quote)
					.isLessThan(LmdbNativeWork.SEEK + rowsPerObject * 4D);
			assertThat(quote.scannedRows()).as("no residual filtering on a covered prefix")
					.isCloseTo(rowsPerObject,
							org.assertj.core.data.Percentage.withPercentage(50));
		}
	}

	/** The same pattern on a {@code spoc}-only store must price as a sweep with a finite ceiling, not as unknown. */
	@Test
	void missingIndexIsPricedAsSweepNotUnknown() throws IOException {
		try (Fixture single = Fixture.open(directory.resolve("single"), "spoc", false);
				Fixture pair = Fixture.open(directory.resolve("pair"), "spoc,posc", false)) {
			int mask = LmdbNativeAccessFacts.PREDICATE | LmdbNativeAccessFacts.OBJECT;
			LmdbNativeAccessFacts.Quote sweep = single.quote(mask);
			LmdbNativeAccessFacts.Quote covered = pair.quote(mask);
			assertThat(sweep.lmdb().known()).as("a missing index is a sweep, which is finite: %s", sweep).isTrue();
			assertThat(sweep.scannedRows()).as("the sweep visits every row of the smallest index")
					.isGreaterThanOrEqualTo(SUBJECTS);
			assertThat(sweep.lmdb().low()).as("the sweep cannot be cheaper than the covered lookup: %s vs %s", sweep,
					covered).isGreaterThan(covered.lmdb().high());
			assertThat(sweep.residualFields()).as("spoc covers neither the constant predicate nor the object")
					.isEqualTo(2);
		}
	}

	/**
	 * Adding an object-led index turns the sweep into a prefix-range walk. Without node-degree statistics the range
	 * size is bounded only by the source, so the floor drops to a seek while the ceiling cannot yet improve; adding the
	 * index that covers the predicate as well (posc) lowers the ceiling too.
	 */
	@Test
	void extraIndexLowersThePrice() throws IOException {
		try (Fixture single = Fixture.open(directory.resolve("single2"), "spoc", false);
				Fixture extra = Fixture.open(directory.resolve("extra"), "spoc,ospc", false);
				Fixture covering = Fixture.open(directory.resolve("covering"), "spoc,posc", false)) {
			int mask = LmdbNativeAccessFacts.OBJECT;
			LmdbNativeAccessFacts.Quote sweep = single.quote(mask);
			LmdbNativeAccessFacts.Quote indexed = extra.quote(mask);
			LmdbNativeAccessFacts.Quote covered = covering.quote(mask);
			assertThat(indexed.lmdb().low()).as("ospc turns the sweep floor into a seek: %s vs %s", indexed, sweep)
					.isLessThan(sweep.lmdb().low());
			assertThat(indexed.lmdb().high()).as("the residual walk is never priced above the sweep")
					.isLessThanOrEqualTo(sweep.lmdb().high());
			assertThat(indexed.residualFields()).as("ospc leads with the object; the constant predicate is residual")
					.isEqualTo(1);
			assertThat(covered.lmdb().high()).as("posc covers predicate and object: %s vs %s", covered, sweep)
					.isLessThan(sweep.lmdb().low());
		}
	}

	/** With adjacency on, the low comes from the adjacency estimate while the LMDB ceiling stays finite. */
	@Test
	void adjacencyGivesTheFloorAndLmdbKeepsTheCeiling() throws IOException {
		try (Fixture fixture = Fixture.open(directory.resolve("adjacency"), "spoc,posc", true)) {
			LmdbNativeAccessFacts.Quote quote = fixture.quote(LmdbNativeAccessFacts.SUBJECT
					| LmdbNativeAccessFacts.PREDICATE);
			assertThat(quote.adjacency()).as("adjacency index serves a node-led probe: %s", quote).isNotNull();
			assertThat(quote.adjacency().known()).as("adjacency work is bounded by its node-predicate upper")
					.isTrue();
			assertThat(quote.lmdb().known()).isTrue();
			// the statement-access arbiter prefers adjacency unless LMDB lies entirely below it
			LmdbNativeWork expected = quote.lmdb().beats(quote.adjacency()) ? quote.lmdb() : quote.adjacency();
			assertThat(quote.combined()).isEqualTo(expected);
			assertThat(quote.combined().known()).as("the selected candidate is finite: %s", quote).isTrue();
		}
	}

